/** Events sent by the OS hook (hooks/loopme-hook) to the `reportEvent` function. */

export type HookEventType = 'start' | 'stop';
export const HOOK_EVENT_REASONS = ['login', 'logout', 'lock', 'unlock', 'sleep', 'resume'] as const;
export type HookEventReason = (typeof HOOK_EVENT_REASONS)[number];

export interface HookEvent {
  /** Generated by the hook; makes retries from its offline queue idempotent. */
  eventId: string;
  type: HookEventType;
  /** When it happened on the device (not when it was received). */
  at: Date;
  /** The device's IANA time zone, which decides the local day. */
  tz: string;
  reason: HookEventReason;
}

/** What `reportEvent` did with an event (stored on `hookEvents/{eventId}`). */
export type HookEventResult =
  | 'started'
  | 'already-running'
  | 'stopped'
  | 'closed-stale'
  | 'no-running-period'
  | 'stop-before-start'
  | 'duplicate';

/** `hookEvents/{eventId}`: audit log of received events, readable by the owner. */
export interface HookEventRecord extends HookEvent {
  deviceId: string;
  result: HookEventResult;
  receivedAt: Date;
}
